const formatReport=lines=>{const out=[],gap=()=>{if(out.length&&out.at(-1)!=='')out.push('');};let code=false;for(const part of lines)for(const line of part.split(String.fromCharCode(10))){if(line.startsWith('~~~')){if(!code)gap();out.push(line);code=!code;if(!code)gap();continue;}if(code){out.push(line);continue;}if(line.startsWith('|')){while(out.at(-1)===''&&out.at(-2)?.startsWith('|'))out.pop();if(out.at(-1)&&!out.at(-1).startsWith('|'))gap();out.push(line);continue;}if(line.startsWith('#')){gap();out.push(line);gap();continue;}if(line&&out.at(-1)?.startsWith('|'))gap();out.push(line);}return out.join(String.fromCharCode(10));};
