const n=v=>v.toLocaleString('en-US'),m=v=>(v/1048576).toFixed(2),pct=v=>((v-1)*100).toFixed(2)+'%',link=(label,file)=>'['+label+']('+file+')',maxContact=Math.max(...hull.contact.map(r=>r.maxNormalContactDistance)),maxSample=Math.max(...hull.contact.map(r=>r.maxSampledDistance)),maxInner=Math.max(...hull.innerWalls.map(r=>r.maxPlanDeviation)),maxPhone=Math.max(...phone.rows.map(r=>r.maxNormalContactDistance)),lines=[];const add=(...s)=>lines.push(...s,'');
add('# LEO hull rollout — verified local build','Base **3d69e54** (main through **6a2d28a**), branch **feat/ship-redesign**. The rollout is selected only by **LEO_LAYOUT=2**. No commits, pushes, branch changes, deployments or communications drafts were made.','All 2,420 hull interfaces are converted: **2,213 outer cabins**, **ten sky gardens**, **97 other frontages owned by 81 rooms**, and **100 shuttle bays**. Counts remain **5,028 cabins and 10,000 berths**.');
add('## Public walk startup gate','The measured page is **dist-v2/walk.html**, with the shipped public bundle '+publicBundle+'. Baseline and candidate use fresh dedicated headless Chrome profiles on this machine, sequentially, at 1280 × 720 with D3D11 and cache disabled.','| Measure | 179d813 in this pair | Final public v2 | Gate |','|---|---:|---:|---:|','| dataset.ready | '+(perf.baseline.readyMs/1000).toFixed(2)+' s | '+(perf.candidate.readyMs/1000).toFixed(2)+' s | '+(perf.limits.readyMs/1000).toFixed(2)+' s |','| Longest task after first status | '+(perf.baseline.maxLongTask/1000).toFixed(2)+' s | '+(perf.candidate.maxLongTask/1000).toFixed(2)+' s | 5.00 s |','| Peak observed V8 JS heap | '+m(perf.baseline.peakJSHeap)+' MiB | '+m(perf.candidate.peakJSHeap)+' MiB | '+m(perf.limits.peakJSHeap)+' MiB |','| Peak observed external backing storage | '+m(perf.baseline.peakBackingStorage)+' MiB | '+m(perf.candidate.peakBackingStorage)+' MiB | separate diagnostic |','The gate includes tasks spanning the first status update. V8 heap is measured with CDP and GC trace counters; page performance.memory and external backing storage are separate diagnostics. Candidate peak backing storage is '+m(perf.candidate.peakBackingStorage)+' MiB. See '+link('paired public measurements','startup/current-comparison.json')+' and '+link('full phase and heap samples','startup/current-v2.json')+'.');
add('The control HTML, public manifest and JavaScript bundle are pinned to the measured 179d813 snapshot in scripts/startup-baseline-v2.json. A separate 390 × 844 touch/reduced-motion public load reached ready in '+(touchStartup.readyMs/1000).toFixed(2)+' s with no page errors: '+link('smoke result','startup/touch-reduced-motion.json')+'. This is desktop Chrome emulation, not phone hardware timing.');
const phases=[];for(const r of perfAfter.statuses){const label=r.text.replace(/\s+\d+%$/,'');if(phases.at(-1)?.label!==label)phases.push({label,at:r.at})}add('| Loading phase | Start after navigation | Elapsed to next phase |','|---|---:|---:|');for(let i=0;i<phases.length;i++){const p=phases[i],end=phases[i+1]?.at??perfAfter.readyMs;add('| '+p.label+' | '+(p.at/1000).toFixed(3)+' s | '+((end-p.at)/1000).toFixed(3)+' s |')}
add('The preserved defective public bundle fails ready, long-task and heap limits under the current headless harness: '+link('known-bad result','startup/known-bad-negative-comparison.json')+'. The complete before-phase and CPU measurements appear below.',
'The complete normal LEO_LAYOUT=2 npm run build completed in '+buildMinutes.toFixed(1)+' minutes on this machine (startup-normal-v2-build19.log), including all raw producers, facade finalization, prepared authoring and lossless encoding. This is offline compilation time. Earlier continuations exposed a fixed-signs adapter anchor and a 30-minute offline deadline; the hook is corrected and that build-only cap is now 60 minutes (configurable with LEO_PREPARED_BUILD_TIMEOUT_MS). Public limits remain unchanged. The phone fitting and frame repairs are included in that full build. The subsequent seam-preserving phone refinement was rebuilt through the normal exterior producer and its shared phone-only branch; the plain full build uses that same implementation. The normal public producer and verification commands below were run on the final bytes. The owner should run the complete default build commands below outside the sandbox.',
'All fixed hull clipping, skin authority, aperture/envelope cuts, guard planning, static ownership and collision preparation now run in the normal v2 producer. The public walk loads prepared render geometry, versioned serialized BVHs, rest spots and fixed feature templates. Runtime controllers retain privacy, distance culling, doors, lifts and interactions. Cabin cores stay instanced. The full flood uses this same prepared collision artifact **'+prepared.artifact+'**.',
'The actual decoded static render bands, retained instances and cached proxies/lounge also pass the 5 cm skin and protected-window test: '+link('prepared surface proof','prepared-skin-clearance.json')+'. The public decoder verifies '+n(prepared.arraysVerified)+' typed arrays byte-for-byte in the normal prepared gate. Input/source fingerprints reject stale assets. The standalone startup check also verifies the public HTML, bundle path and all prepared transport bytes against the current artifact, preventing a stale dist directory from passing. Exact vertex dictionaries, lossless Meshopt/Zstd transport and compact offline collision trees preserve coordinates, normals and all oriented triangles; no prepared walk mesh is simplified or quantized. Shared compressed GLB blocks reconstruct each model with its original packed SHA-256. Every reconstruction table and prepared part is included in the byte budget. The intermediate uncompressed package was too large; prepared transport fell from 176,818,820 to 149,839,236 and then to '+n(preparedSize.compressedBytes)+' bytes through the measured lossless changes.',
'An unchanged normal rebuild may reuse prepared geometry only after verifying every input fingerprint and transport byte. Cached geometry proofs also require the complete current model identity in both the parent proof and linked surface/guard reports. Updating the phone asset now invalidates stale linked reports and reruns their audit; an input mutation during the audit also fails. The retained stale-identity case is in startup/prepared-cache-identity-regression.json. Producer, codec and runtime source changes invalidate that cache. npm run check:startup is included in the normal v2 check sequence; it requires ready within min(85 s, measured baseline), tasks at most 5 s, heap at most 110% of baseline, and no page errors.');
add('Complete positive raw-asset proofs can be reused only when the current full model identity, exact report SHA, all five asset SHAs, checker and authority bytes still match. Subset, filtered, failed and negative runs never reuse that cache. The final retained bad guard asset was checked again after the positive cache was written and still failed.');
const afterCPU=await get(dir+'/startup/after-hotspots.json');assert.equal(afterCPU.bundle,publicBundle);const beforeCPU=await get(dir+'/startup/known-bad-negative-hotspots.json'),beforeStartup=await get(dir+'/startup/known-bad-negative-v2.json');assert.equal(beforeCPU.bundle,negativeStartup.assets.candidate.bundle);
add('The fresh paired CPU recording is in '+link('after-hotspots.json','startup/after-hotspots.json')+'. The following are sampled self costs, separate from the unprofiled gate and wall-clock phase table. The removed hull-fitting and retirement work no longer appears in public startup.','| Remaining CPU step | Sampled self time |','|---|---:|');for(const r of afterCPU.selfHotspots.filter(r=>r.file&&r.selfMs>0).slice(0,6))add('| '+r.function+' · '+r.file.split(/[\\/]/).at(-1)+' | '+(r.selfMs/1000).toFixed(3)+' s |');
const gpuCPU=afterCPU.selfHotspots.find(r=>r.function==='onFirstUse'),decodeCPU=afterCPU.selfHotspots.find(r=>r.function==='readPreparedWorld');if(gpuCPU&&decodeCPU)add('The largest remaining self costs are Three.js shader/program first-use setup ('+(gpuCPU.selfMs/1000).toFixed(3)+' s) and prepared-world decoding ('+(decodeCPU.selfMs/1000).toFixed(3)+' s). Device-specific WebGL program, uniform and texture setup remains in the browser; static hull fitting, cuts, ownership and collision compilation do not.');
add('The current checker was also allowed to finish a full profiled load of the preserved defective public snapshot. It reached '+(beforeStartup.readyMs===null?'the capture deadline without ready':('ready at '+(beforeStartup.readyMs/1000).toFixed(2)+' s'))+', with '+(beforeStartup.maxLongTask/1000).toFixed(2)+' s longest task and '+m(beforeStartup.peakJSHeap)+' MiB peak V8 heap. All public startup limits remain unchanged. See '+link('complete before phase samples','startup/known-bad-negative-v2.json')+' and '+link('fresh before CPU analysis','startup/known-bad-negative-hotspots.json')+'.','| Before loading phase | Start after navigation | Elapsed to next phase |','|---|---:|---:|');const beforePhases=[];for(const r of beforeStartup.statuses){const label=r.text.replace(/\s+\d+%$/,'');if(beforePhases.at(-1)?.label!==label)beforePhases.push({label,at:r.at})}for(let i=0;i<beforePhases.length;i++){const p=beforePhases[i],end=beforePhases[i+1]?.at??beforeStartup.readyMs;add('| '+p.label+' | '+(p.at/1000).toFixed(3)+' s | '+(end===null?'unfinished':((end-p.at)/1000).toFixed(3)+' s')+' |')}
add('The largest before costs are inclusive CPU samples and overlap where one function calls another; they must not be summed.','| Before CPU step | Inclusive sampled time |','|---|---:|');for(const name of ['retireLegacySkinGeometry','fitPrototypeStructure','createSkinAuthority','createHaze','attachFacade','fitV2Structure']){const r=beforeCPU.inclusiveHotspots.find(r=>r.function===name);if(r)add('| '+r.function+' | '+(r.inclusiveMs/1000).toFixed(2)+' s |')}


add('## Decoded geometry and drop protection','The normal plan gate consumes the byte-verified actual public decoder output for the exterior/window, finish and all-occupied-room guard checks; it retains the complete independent finite-face skin contact and pure ownership checks. The proxy clearance report is explicitly a subset of that complete decoded-render proof, with its parent report SHA recorded. The actual public decoder output passes both the exterior/window audit and the same full-volume coplanar finish query used by check-plan. Every decoded inner hull wall is also compared with its finite planned inner faces within 0.1 mm: '+link('prepared finish and ownership proof','prepared-finish-geometry.json')+'. The normal check verifies all decoded array SHA-256 values and keeps byte-identical mutable instance buffers independent for doors and culling.','The first complete flood of the prepared world exposed real perimeter and boarding-platform/stair drops, and an upper edge beside the observation-lounge access ramp. All 27 direct procedural-versus-prepared boundary probes agreed, so these were repaired in the normal producer. Guards now use actual floor/tread triangles, include room and ramp void edges, and no longer discard a real drop merely because its position falls in a room polygon. The support classifier explicitly includes Deck_slab and Shuttle_boarding_bridge; omitting those names in the first revised guard plan had removed valid atrium guards and closed real boarding crossings. Floor-support fixtures cover both names. Boarding stairs receive continuous sloped glass balustrades with a top rail; platform guards leave the real stair and bridge approaches open. The full flood also rejects unapproved drops classified as other, rather than checking only the previously named void categories. The two named furniture-back drop exceptions are unchanged. Bay floors retain explicit floor-role metadata for support planning. Each of the 100 bay-extension floor perimeters is tested against actual ground and walls; unsupported sides receive continuous glass balustrades with top rails, while level bank and boarding approaches remain open. A targeted replay of all 18,022 earlier failing transitions is blocked, including the 29 real open bay-side drops; the complete final flood is still the acceptance proof. The compiler also saves the registered room anchors and their original baseline matrices; public runtime and the flood restore that registry without applying frame transforms twice. A round-trip fixture verifies room ownership, baseline matrices and unchanged world transforms. V2’s fixed wayfinding signs are captured as a separate prepared graph and loaded directly, including their textures. They participate in the actual exterior/window audit. The retired v1 corridor-trim producer remains disabled in v2.','The generic render-bake overlap nudges are disabled for Deck_slab, V2_glass_wall, finished pressure skin, room envelopes and meshes already cut to the skin or window reservations. The actual prepared audit exposed 107 interfaces with narrow slab/floor overlaps introduced by nudging previously correct slab edges; positive/negative regressions reproduce the old movement and verify byte-exact oriented slab and cut-glass-wall triangles after the v2 bake. Six original room cores also had clean source glass but overlapping post-nudge faces; retaining their exact geometric cuts resolves those overlaps. Their surfaces are resolved by the geometric finish gate; a later 2 mm move must not put a gallery or guard back into a reveal. Coarse triangles are checked at edge midpoints and centroids during clipping. The finished web authority is captured before legacy walk cuts. The crown-shaft cut changes oriented winding at remote projection seams; deriving the field afterward had classified three real outboard pieces as inside. Exact canonical oriented-triangle SHA-256 signatures now bind the raw guard plan and prepared manifest to an independent extraction of the untouched web. The build rejects a mismatch before expensive authoring, and the decoded geometry gate repeats the comparison. Canonical cyclic orientation and sorting retain duplicate faces and every exact Float32 coordinate while allowing lossless index reordering. Each clipped Float32 result is retested until the same clip produces no further changes, with a bounded convergence limit. A clipped polygon introduces new fan edges and probe positions that its parent did not contain; the immutable authority and fixed-point check remove the three residual seam pieces without changing the 5 cm rule. The actual three-piece proof also passes a fresh independent skin oracle. The canonical field exposed a Deck 19 ceiling fan that the old clipper kept emitting unchanged. Clipping now certifies saved Float32 vertices, edge midpoints and centroids on every output face, exposes known outside probes during subdivision, and subdivides the original face when an emitted fan still crosses a seam. Exact zero-area emissions are omitted. Unresolved unsafe microcells are removed only at an edge resolution of at most 1 mm; this is conservative cropping, with the external 50 mm limit unchanged. The exact failed Deck 19 ceiling, all twenty source ceilings, the original affected cabin batches, and portable non-linear/seam/zero-area regressions pass. Clipping cannot use an interior centre sphere to skip vertices across an axial projection seam. Each cut intersection is certified after local and world Float32 rounding, with a small inboard bias and adaptive backoff; the 5 cm gate remains unchanged. Prepared audit parts retain their original batch flag so the garden frame faces participate in the actual finish/contact query. Inherited Lounge_additive_glow dressing is now included in perimeter retirement. Exact zero-area faces do not render and are excluded consistently from both raw and decoded audits.','Narrow projection gaps in trimmed skin triangles are classified against the actual oriented mesh using 14 oblique rays, requiring at least 12 positive winding results for a deep interior point. This corrects the measured false outboard result nine metres inside the bow. The 5 cm exterior failure limit is unchanged, and positive/negative seam fixtures plus the saved bad guard export test it.','Two bounded retained service-fitting families are named in the exterior exception list: exposed fin inspection balconies and their rails/glazing above Deck 20, and crown lift headgear/shaft termination above the crown roof. The names and measured spatial bounds prevent these exceptions applying to cabin or public-room windows. They remain subject to the protected-window obstruction gate. They are not additions to the drop allow-list.');
add('## Final flood repairs beneath the real skin','The previous complete flood rejected two roof gaps and 47 unguarded transitions. These were retained as failures in startup/build11-full-flood-fail.json; they were not added to the allow-list. The new full flood below is run on the rebuilt public prepared geometry.','The 47 transitions were at four genuine interior atrium edges on Decks 7 and 9. The distance classifier stopped at a nearby internal wing face before testing the enclosing pressure body, removing parts of otherwise valid guards. It now evaluates every enclosing component and uses their signed union. The four continuous 18 m glass-and-top-rail runs are retained, 72 m in total. The same change has positive and negative enclosed-wing fixtures. void-guard-regression.json now replays all 96 pointed-edge and internal-atrium transitions.','The two roof openings were in N07-483 on Deck 12, beneath real inward pockets in the finished bow skin. Extending a farthest-radius bound across those pockets would misrepresent the skin and was rejected. The normal producer screens all 2,213 outer cabins against the untouched finished web, then fits a local painted soffit where required. Nine Deck 12 cabins need one: three have a 3.0 m window-zone ceiling and six have a 2.8 m ceiling. Each starts at local depth 5.5 m, beyond the frozen furniture core. The core keeps its 3.4 m ceiling, original corridor wall, door and furnishings. Windows keep their size and sill. The stepped return and both ceiling coves are visible finishes, merged into the existing deck/material batches. Buried diffuser top caps are removed physically; no coplanar exception was added.','The fit-input web and final decoded web have the same exact oriented-triangle skin signature (startup/ceiling-fit-source-skin-proof.json), despite final GLB pruning and metadata normalization. The affected-room alternatives and selected profiles are in '+link('normal ceiling fit','cabin-ceiling-profiles.json')+'. In N07-483, the actual clipped source shell still has open headspace with 3.2 m, 3.0 m and 2.9 m soffits; 2.8 m closes it. The normal class search selects the highest passing 0.2 m class. The actual decoded public roof and wall faces pass the finite standing-headspace closure query in all nine rooms. Its 0.1 mm distance and 1 cm² area limits cover Float32 joins only; the exterior contact limit stays 5 cm. New clipped or subdivided backing faces must also be strictly inboard, while untouched source faces retain the original contact allowance. The original backing fixture, all twenty source ceilings and dense curved-surface fixtures pass.','Supplementary native views of N07-483: '+link('soffit gallery','soffit-captures.html')+'. '+soffitNative.captures.map(c=>link(c.kind,c.image)).join(' · ')+'. These are additional views; the required eight-room cameras remain matched to the previous review.');
add('The first complete normal check also caught one Wing_thermal_edge fragment in N01-027’s phone window. Phone fitting cuts had used a different skin envelope from the independent outermost-field window gate. The shared normal exterior producer now reserves that same phone surface with conservative finite prisms before trimming the thermal-edge fitting. The retained bad phone fails and the repaired fitting passes the unchanged checker; see skin-clearance-phone-fitting-negative.json and skin-clearance-phone-fitting-positive.json. A consistency guard then caught exterior re-export drift from reserializing the fitted Float32 envelope data. The normal layout producer now retains its pre-fit exterior input separately; the normal exterior producer validates its geometric agreement with the interior input within 1 micrometre of storage aliasing, and consumes that immutable input. This does not change the independent 5 cm contact rule. The complete normal exterior producer and facade finalizer were rerun using it after this repair. Their recorded byte comparison confirms every non-phone model, layout and walk plan stayed identical, and the prepared walk artifact stayed '+prepared.artifact+'. The phone gained 991 triangles for the additional clean cuts. No exception or tolerance changed. All acceptance and fresh public startup were repeated under the new model identity.');
add('On the saved pre-normal-seam phone, the complete audit also caught three garden-mullion vertices and one face probe 51.580 mm outboard of the web skin, exceeding the 50 mm limit by 1.580 mm. The normal shared phone producer now moves only garden-frame vertices another 20 mm inboard along their owning chart; glazing, pressure skin, triangle count and materials are unchanged. On that saved input, every frame vertex and triangle edge/centre was measured: another 5 mm gives a 48.302 mm bound, 10 mm gives 45.023 mm, and the selected 20 mm gives 38.467 mm. The additional margin survives Float32 rounding; no tolerance was widened. The complete phone asset passes both outside/window checks and all 2,420 own-surface contacts. See '+link('measured frame alternatives','startup/phone-frame-inset-alternatives.json')+' and '+link('saved frame negative','skin-clearance-phone-frame-negative.json')+'. The final phone was rebuilt by the normal exterior producer --phone-only branch, which the plain full build also calls through the shared producer. Its normal finalizer and complete-phone gates passed. At that earlier phone-only step, the non-phone models, fitted plan and prepared artifact stayed byte-identical. The later lounge rebuild regenerated its own complete prepared artifact and physical proofs.');
add('## Final lounge and phone corrections','The fresh image review still found capped V2_guard_glass pieces above the observation-lounge window band after the earlier numerical gates passed. Rays identified old Deck 18/19 slab islands just outside the inset room sections, inside the full occupied lounge projection. The old room-scoped support audit missed that region. The normal v2 structural producer now subtracts the complete lounge floor projection from intermediate Deck_slab and distribution-ceiling geometry. The actual approach ramp, explicit stairs, promenade, room floor and all frozen cabin/circulation data remain. The regenerated raw walk plan contains no guard rows in the observed window-band region.','The new finite room-slab-void gate runs on actual decoded public render bands within check-plan. It rejects the saved pre-fix public artifact with '+slabBad.intersections+' intersecting faces, '+slabBad.totalArea.toFixed(3)+' m2 of rendered face overlap (including both slab sides and ceiling faces), and a largest intersection of '+slabBad.maximumArea.toFixed(4)+' m2. The final decoded artifact has zero intersections above the 1 cm2 Float32 joint residue threshold. That precision allowance does not change the 5 cm contact rule. The full-height lounge projection is also included in the guard-support query; its report is byte-bound into the parent prepared proof. See '+link('actual old public negative','lounge-slab-actual-prepared-negative.json')+' and '+link('current decoded slab-void proof','room-slab-voids.json')+'.','Phone inspection also found a dark normal smear near the stern. Position-only welding had averaged incompatible normals at old aperture seams, and simplification spread those values across large faces. The normal phone producer now preserves normal seams, includes normal attributes at weight 0.1 in simplification, and uses one shared geometric offset at each coincident position so shading splits do not open physical gaps. The selected phone is '+n(phone.triangles)+' triangles, with '+n(phone.limit-phone.triangles)+' spare; this is '+n(610676-phone.triangles)+' below the owner’s 610,676-triangle snapshot. Four matched opaque pressure-surface rays now agree with the web shader normals; the preserved bad phone fails. The shading test is part of normal v2 check-plan. Normal-only averaging/projection trials left visible bands and were rejected; the selected change fixes the source simplification. All 2,420 phone contacts and the complete phone skin/window gate pass. See '+link('phone shading regression','phone-shading-current.json')+' and '+link('retained shading negative','phone-shading-known-bad.json')+'.');
add('## Capped glass blocks and exterior marks', 'The loose translucent blocks were **V2_guard_glass** and **V2_guard_cap**, made by **src/v2/railings.js** from the slab-edge drop planner. Cropping those rows to floor outlines did not account for the hull lean over the 1.125 m guard height. They were not a second set of cabin windows. The garden equivalents are V2_garden_guard_glass and V2_garden_guard_cap; they receive the same skin and window-reservation clipping. Viewport_structural_mullion, Continuous_window_ledge, Panoramic_viewing_rail and Viewing_rail_post were inherited observation-facade fittings and are removed in v2. The room lining now closes the hull boundary; outboard guard runs are removed rather than used as escape barriers. Guards at genuine interior drops remain continuous glass with a continuous top rail, and abutting level runs are joined. The post-merge flood exposed 49 transitions at Deck 13’s pointed atrium edge that the old grid planner missed because it mistook low geometry for a guard. Exact void-boundary guards now follow those angled edges. The first guard clipping pass also discarded valid interior spans at pressure-mesh window holes: its pressure-only axial profiles had no sample there, although the points are more than 17 m inside the complete finished body. Guard clipping now uses the same complete finished-web authority, including glazing, with a 0.30 m inboard placement margin over the full glass and cap height. The separate exterior failure limit remains 0.05 m. They query real ground on both sides, leave supported bridge crossings open, avoid full-height walls and replace nearby raster guard steps. These are interior balustrades, not outboard panels; the drop allow-list was not expanded. The expanded 96-transition regression also passes against the final guard plan (void-guard-regression.json). The completed flood then found 48 real lower-deck step-offs where the hull leans outward above the finished floor. Real native Controller.step probes confirmed loss of floor support at both Deck 1 sides and the Deck 2 stern. Continuous painted lower-wall returns now close that floor-to-lining toe on Decks 1–5. They use a 0.20 m normal lining, a 0.80 m knee height, a 2 m maximum return depth and a 1 m profile-jump limit; they have no glass, metal cap or walkable shelf. Window reservations are cut out and no redundant bottom face overlaps the floor. The selected returns contain '+n(retired.lowerWallReturns.triangles)+' triangles; the measured maximum return depth is '+retired.lowerWallReturns.maxReturnDepth.toFixed(4)+' m. The initial unbounded profile alternative produced cap spans up to 16.44 m and was rejected; the selected bounded version keeps the native probes grounded with zero drop. See rollout-perimeter-controller.json for the final normal-scene tests, and perimeter-controller-before.json for the diagnostic before case.', 'The dark bow marks and pale ticks were **Bow_horizontal_panel_reveal**, **Bow_cheek_panel_joint** and **Bow_reveal_line**, small cosmetic strips left after the old facade was cut. Rays at the reported pixels hit them about 6–12 cm before the real skin. All three are now fully retired in every v2 model, rather than cropped into short tabs. A shared retired-name list drives both the producer and the new check. The normal build finishes every GLB with scripts/retire-obsolete-facades-v2.mjs, which also removes unreferenced export data. Its versioned result is byte-stable when repeated. All other retained exterior fittings are cut out of the exact room window reservation, including the wing thermal edge.', 'Legacy pressure lining, distribution-ceiling backing, decorative perimeter geometry and distant facade/haze proxies are clipped to the finished skin. The haze reuses the real holed deck plates before the native render bake, with no inset side wall. Native-only lounge artwork and shader geometry are included in the normal plan gate through the complete actual decoded-render proof: the back mural moves to the inboard wall with door openings cut out, and the left mural and shader roof are fitted inside the skin. The dome, hammocks and lullaby remain. The proxy roof leaves rooms continuing above it open. Backing reservation cells overlap by 1 mm along facet edges, removing Float32 slivers without changing the window dimensions or contact tolerance. Obsolete Commons columns, Bridge window mullions and the old observation-lounge mullions, ledge and viewing rail/posts are retired; garden artwork and reading-shelf dressing are fitted inside the real hull. '+retired.rows.length+' mesh cleanup records are in '+link('perimeter-retirement.json','perimeter-retirement.json')+'. '+retired.moved.length+' retained garden figures are placed on existing galleries at their original height and scale.', 'The final checker rejects the saved pre-fix diagnostic export: '+badProof.rows[0].outside.map(r=>r.mesh+' has '+n(r.vertices)+' outside vertices and '+n(r.faceSamples)+' outside face probes, maximum '+r.maxDistance.toFixed(3)+' m').join('; ')+'. At least '+n(badProof.rows[0].blocked.length)+' protected-window intersections are recorded. This is preserved pre-fix guard geometry, not a claimed fresh pre-fix build of the merge. The proof records its exact asset hash and uses the current finished web authority. See '+link('known-bad result','skin-clearance-known-bad-final.json')+'.', '## New skin and window gate', 'Normal v2 check-plan audits the full walk GLB and all four exterior LODs, bans every retired facade name, and audits the native facade, haze, lounge artwork and effects within the complete actual prepared render graph. Exact zero-area triangles are excluded because they have no rendered surface; the 5 cm limit is not changed. It checks referenced geometry vertices and coarse-face edge/centre probes against the finished web skin at 5 cm, and performs finite triangle clipping against each room window reveal and the first 1 m beyond its glass. A 50 mm conservative reservation accounts for the permitted glass fitting error; the skin tolerance stays 50 mm. Only that room’s own glazing and reveal/frame may occupy its window reservation. The native haze and facade subset report records the parent proof SHA and uses that same authority. All five raw asset proofs and the native proxy proof must match the current walk build identity. A complete positive raw-asset report is reusable only when its five model hashes, complete layout/source identity, oracle code and source-data hashes, and exact report SHA remain unchanged. Partial or failed reports never populate this cache; CLI negative/subset probes always audit again. The saved bad guard export is rejected again after the positive cache is written. ', 'The clearance oracle loads the actual finished leo-exterior-web.glb. The producer captures that same untouched geometry before crown/wing walk cuts, using an immutable authority shared by all fitting and guard planners. Its exact canonical signature is '+prepared.clearance.skinAuthority.signature+'. Orthogonal outermost mesh fields determine containment independently of smoothing normals. Opaque patches closing retired apertures are included. Where a narrow trimmed seam has no axial column, the nearest actual geometric face plane, oriented away from the measured body centre, determines which side is inside; this local seam test is limited to 0.30 m from a real face. It preserves the solid bow lining that the earlier column-only classifier wrongly trimmed. It does not enlarge the 50 mm exterior allowance; the regression fixture still rejects a pane 60 mm outside at the same seam. The crown floor opening is an internal lift opening above its measured floor level. A 30 micrometre projected weld handles Float32 triangle seams; the physical tolerance remains 50 mm. The crown structural floor is part of its actual exterior skin. For the phone representation only, skin/glass vertices use its independent surface, as accepted in the phone gate; its furnishings and frames still receive the web clearance check. Named propulsion, control-surface, service/branding and retained fin/nacelle joinery fittings are listed with reasons in the proof; none is exempt from the window reservation.', '| Asset | Outside meshes | Obstructions |', '|---|---:|---:|', ...clearance.rows.map(r=>'| '+r.tag+' | '+r.outside.length+' | '+r.blocked.length+' |'), '| Native facade, haze and lounge dressing | '+proxies.outside.length+' | '+proxies.blocked.length+' |', link('Complete current clearance proof','skin-clearance-current.json')+' · '+link('Native proxy proof','native-proxy-clearance.json')+' · '+link('Regression fixtures','../../scripts/check-skin-clearance-fixtures-v2.mjs')+'.');
add('The tall observation lounge also contained '+n(badRoomGuards.removed.length)+' obsolete raster guard runs ('+badRoomGuards.removedMetres.toFixed(1)+' m), floating 2.0 m above its actual V2_outer_room_floor. They sat inside the skin, so the exterior-only test could not catch them. The raster producer now checks actual ground below each retained span, with a 0.22 m tread allowance and inboard floor-edge probes. Unsupported pieces are removed; explicit stair and exact void balustrades retain their own planners. The normal plan gate checks actual prepared floor support inside every occupied room core and non-cabin hull extension, including the upper lounge and full-height gardens. Its preserved lounge case fails and the final ship passes. See '+link('before floor rays','lounge-floor-support-before.json')+', '+link('rejected floating guards','room-guard-support-known-bad.json')+' and '+link('current room guard support','room-guard-support.json')+'. The final raster plan removes '+guardPlan.guardSupport.removedMetres.toFixed(1)+' m of unsupported candidates across the ship. The independent retained-span audit resolves narrow real floor strips at 5 mm lateral spacing within the original 0.4 m allowance; it preserves the 0.22 m vertical limit and has positive narrow-strip and negative floating-rail fixtures.');
add('The small shape still visible far through N05-026’s stern window is a genuine **'+podInside.length.toFixed(2)+' m continuous pod maintenance balustrade**, V2_guard_glass with V2_guard_cap, seen almost edge-on about 70.7 m from this camera. Its sampled pane/cap envelope points lie at least '+(-podInside.maxDistance).toFixed(3)+' m inside the finished nacelle skin, with Pod_maintenance_floor on one side and no ground within 10 m on the other. It already has a continuous top rail and is retained for that real internal drop; it is not a pane standing outside the cabin hull. See '+link('pixel-ray identification','stern-pane-ray-identification.json')+', '+link('floor/drop measurements','stern-post-side-floors.json')+' and '+link('skin containment','stern-pod-guard-inside.json')+'. '+link('Native view of the continuous balustrade','retained-pod-balustrade-inside.png')+'.');
add('## Hull and finish gates','The retained, finished web exterior is the authority. The original 2.5 m inset was a conservative geometric allowance, with roomHalf also checking 2.5 m above and below the room; it was not a 2.5 m solid pressure wall. The inset lining separately protected bare distribution slabs from walkable exterior triangles. New occupied floors and lining continue to the real pressure skin. A 0.20 m normal wall build-up replaces the blanket setback. Reservations are now explicit: existing 0.12 m party walls, the 2 m by 0.7 m capsule and furniture approaches, plus the frozen corridor, shaft, wing and launch clearances. Source profiles retain the skin lean across the complete room width and height; the analytic hull-v2.js outline is not used as the contact oracle.','The wall is the hull: the original outer skin supplies the outside face, the room lining is its inner face, and the reveal spans that build-up. Glazing is flush or approximately 0.02 m inboard of the outside face. Old exterior apertures are closed before current room-owned windows are cut. Cabin windows are 2.2 × 1.3 m at a 0.8 m sill; public windows are 3.0 × 2.2 m; working and bay windows are 3.0 × 1.4 m. Gardens have full-height hull glazing.','| Gate | Result |','|---|---|','| Finished web contact | '+n(hull.contact.length)+' interfaces PASS; complete finite-face distance bound '+(maxContact*1000).toFixed(3)+' mm, maximum sampled distance '+(maxSample*1000).toFixed(3)+' mm; limit 50 mm |','| Skin-bound wall lining | '+n(hull.innerWalls.length)+' interfaces PASS; maximum plan deviation '+(maxInner*1000).toFixed(4)+' mm |','| Coplanar finishes | '+n(hull.plan.interfaces)+' converted interfaces and '+n(hull.coreFinishVolumes)+' original room/bay core volumes PASS |','| Ownership and frozen footprints | No cross-owner floor overlap; all 5,028 entries and corridor thresholds pass |','| Independent phone contact | '+n(phone.rows.length)+' interfaces PASS against the phone surface; bound '+(maxPhone*1000).toFixed(3)+' mm |','| Streamed skin parity | All four public exterior payloads match the exact finished web/phone skin |');
add('The contact tolerance remains 5 cm. The coplanar test uses the actual finished floor and ceiling underside, a 0.5 mm plane comparison and a Float32 shared-edge precision of 1/32768 m. A real 0.1 mm-wide overlap is rejected. Query fragments retain their physical triangle identity. Collision-only panes are excluded from rendered-finish comparisons. The only coplanar exceptions are:');for(const e of hull.exceptions)add('- **'+e.id+'** — '+e.reason+' ('+n(e.contacts)+' contacts).');
add('Floors below the occupied finish and backing above the ceiling underside are outside that room volume. Public core finish is 6 mm above its structural datum, with a 100 mm ceiling build-up; bay cores use the actual 120 mm ceiling underside. No exception permits a visible duplicated floor, ceiling, lining or hull pane. Full proofs can be reused only when all model, plan, source, checker, dependency and authority bytes match.');
add('## Geometry, furniture and frozen layout','The corridor-side cabin wall, corridor network, inner rows, wings, atrium, cabin ids/types/doors/berths and original furnishing cores retain the accepted blueprint. End wedges belong to existing owners, with no new cabins. Planned garden assemblies and craft placements retain the frozen signature **'+identity.invariants.sha256+'**.','Cabin cores remain instanced. Variable shells, reveals and glazing are batched by deck/material with physical face ownership retained through export and Meshopt reordering. Window lounges use fixed depth classes: two usable seats, low table, rug, floor lamp and plant; the original desk and chair remain. There are '+n(walk.loungeSeats.total)+' new lounge seats. Garden frames and mullions are merged into deck/material batches.','The finish work also removes old slabs beneath owned cabin/bay floors, redundant wall-panel caps and duplicate coplanar cut emissions. A cut face on a boundary is emitted once; area conservation and repeated-cut fixtures cover both cutter paths. Same-owner lining caps are removed from connected original room volumes. Bays gain 1.8 m inboard openings while keeping the original side entries. Four named bank-access portals join the aft starboard bays on Decks 2 and 3 through their maintenance/inspection bulkheads, across the existing 2.6 m bank floor; all existing primary entries remain fixed. These access strips and frozen craft cores participate in the ownership gate. The native arena floor inlay has clean butt joints in v2; its original v1 producer is unchanged.','The native distant facade now preserves every structural slab opening, including the observation lounge’s intermediate-deck void. The proxy also subtracts the occupied room and hull-extension footprints through each plate’s full thickness, using the real leaning profiles. The normal check-plan gate probes original and real-skin room volumes at three heights through every intermediate plate; the normal check also probes every original slab void. A visual proxy cannot restore a false ceiling across the lounge or its window.',
'Facade ownership: **'+n(facadeProof.rows.reduce((s,r)=>s+r.samples,0))+'** actual proxy ray probes pass across original room cores and the real-skin extensions at three heights through the intermediate deck plates. See '+link('facade room proof','facade-room-report.json')+'.',
'Minimap: all **'+n(map.drawnCells)+'/'+n(map.extensionCells)+'** sampled extension cells beyond the old slab outlines are drawn in the actual normal PNG.');
const poolProof=await get(dir+'/shared-model-transport.json');assert.equal(poolProof.status,'PASS');assert.equal(poolProof.compressionLevel,19);assert.equal(poolProof.decodedPieceBytes,4194304);add('Public GLB pools use Zstd level 19 with unchanged 4 MiB decoded pieces. A diagnostic on the previous pools saved 3,036,640 bytes compared with level 16; 12 MiB pieces saved only another 323,282 bytes, so the smaller pieces are retained. Every final reconstructed GLB is checked byte-for-byte by the normal public producer: '+link('shared transport proof','shared-model-transport.json')+'. This affects transport bytes only; prepared geometry and collision data remain unchanged.');
add('## Walk acceptance','Full flood build identity: **'+walk.buildIdentity.hash+'**.','The flood uses the native 2 m tall, 0.7 m wide capsule on a 0.35 m lattice, with real floor and body collision probes. Step-off transitions are checked throughout the reached graph; overhead open-to-space rays sample every thirteenth reached position.','| Check | Result |','|---|---:|','| Reachable positions | '+n(walk.positions)+' |','| Safe cabins | '+n(walk.safeReach.cabins)+' / 5,028 |','| Safe program rooms | '+n(walk.safeReach.rooms)+' / '+n(walk.rooms.total)+' |','| Safe lift stops | '+n(walk.safeReach.liftStops)+' / 100 |','| Usable cabin berths | '+n(walk.berths.usable)+' / 10,000 |','| Usable cabin chair spots | '+n(walk.cabinChairs.usable)+' / '+n(walk.cabinChairs.total)+' |','| Usable new lounge seats | '+n(walk.loungeSeats.usable)+' / '+n(walk.loungeSeats.total)+' |','| Usable registered seats and beds | '+n(walk.seatsAndBeds.usable)+' / '+n(walk.seatsAndBeds.spots)+' |','| Room-owned hull window approaches | '+n(walk.hullInterfaces.usable)+' / '+n(walk.hullInterfaces.windows)+' |','| Open to space / exterior falls | '+walk.openToSpace+' / '+walk.voidFalls+' |','| Unapproved drops over 1 m | '+(walk.guardGaps.length+walk.roomFeatureViolations.length)+' |');
add('The four new bank accesses also pass an actual native Controller.step traversal through both the bulkhead and craft opening. Each crossing covers 4.185 m with only a 6 mm floor change; see '+link('native crossing evidence','rollout-bank-controller.json')+'.');
add('Actual native glazing collision: 72 rays across the eight representative windows pass; the maximum hit distance from the real outer surface is '+(Math.max(...solidity.rows.map(r=>r.distance))*1000).toFixed(3)+' mm (limit 50 mm). See '+link('solid-pane evidence','rollout-native-solidity.json')+'.');
add('Standing approaches require the full capsule, real floor support, safe reach without falling and clear sight to the pane. Own glazing stays solid to the walker and transparent to the sight test. The existing named furniture-back step-off allow-list remains narrow:');for(const r of new Map(walk.roomFeatureDrops.filter(r=>r.allow).map(r=>[r.room+'/'+r.support,r])).values())add('- **'+r.room+' / '+r.support+'** — '+r.allow.reason);
await Promise.all(['walk-report','hull-plan-report','phone-plan-report','check-report'].map(n=>fs.copyFile(model+'/'+n+'.json',dir+'/rollout-'+n+'.json')));add('Current gate reports: '+link('complete flood','rollout-walk-report.json')+' · '+link('plan/contact/ownership','rollout-hull-plan-report.json')+' · '+link('phone gate','rollout-phone-plan-report.json')+' · '+link('normal v2 check','rollout-check-report.json')+'.');
add('## Byte and phone budgets','| Measure | v1 | Final v2 | Limit |','|---|---:|---:|---:|','| Raw full ship | '+m(cost.costs.v1Full)+' MiB | '+m(cost.costs.rawFull)+' MiB | '+m(cost.costs.limits.rawFull)+' MiB |','| Unique public model payload | '+m(cost.costs.v1Payload)+' MiB | '+m(cost.costs.publicPayload)+' MiB | '+m(cost.costs.limits.publicBytes)+' MiB |','| Public model/data disk | '+m(cost.costs.v1Payload)+' MiB baseline | '+m(cost.costs.publicDisk)+' MiB | '+m(cost.costs.limits.publicBytes)+' MiB |','| Largest transport piece | — | '+m(cost.costs.maxPiece)+' MiB | 16.00 MiB |','| Phone triangles | '+n(phone.baseTriangles)+' | '+n(phone.triangles)+' ('+pct(phone.triangles/phone.baseTriangles)+') | '+n(phone.limit)+' |','Public totals count the model directory, reconstruction tables, prepared walk geometry/collision/metadata, generated room-data pieces, asset manifest and root GLBs. Raw bytes are '+n(cost.costs.rawFull)+'; public payload/disk bytes are '+n(cost.costs.publicPayload)+' / '+n(cost.costs.publicDisk)+'. Per-model transport rows share packs and are not additive. See '+link('per-model bytes','rollout-model-costs.md')+'.','The phone has '+n(phone.limit-phone.triangles)+' triangles of headroom below its cap. The phone keeps its independent constrained pressure simplification, now using a 0.04 m simplifier error and locked borders. It does not adopt the full web pressure mesh. Lite mode loads exterior geometry only; room and furniture meshes are absent. Closest window inspection uses the original 50 m orbit minimum. This is an asset/contact gate, not a Galaxy S9 hardware performance claim.','Measured phone clearance alternatives: conservative affine reservations produced 620,205 and 619,834 triangles and failed the 611,565 cap. Exact facet reservations with the earlier outside depth used 610,987; the final full-metre glass reservation uses '+n(phone.triangles)+'. Phone garden frames receive the additional 20 mm inward adjustment described above, keeping their tips within the web envelope. Exact sweep-strip floor masks cost 750,856,400 raw bytes and failed the raw cap; the same floor unions now use true perimeter triangulation. The initial public package without current transport sharing/compression cost 364,276,147 bytes and failed. No cabin, berth or room was removed to meet the final limits.');
const startup=await get(dir+'/rollout-native-startup.json');assert.equal(startup.errors.length,0);add('Local dedicated headless walk preparation took '+(startup.readyAfterMs/1000).toFixed(1)+' s for this fresh debug scene. This diagnostic is separate from the paired public startup gate above and makes no FPS claim.');
add('## Native render measurements against 179d813','Five exact native walk cameras, 1280 × 720, pixel ratio 1, 62° FOV. Counters are sampled after shader compilation and warm-up. These are native draw/triangle counters, with no FPS or GPU-time claim.','| View | Baseline draws | Final draws | Change | Baseline triangles | Final triangles |','|---|---:|---:|---:|---:|---:|');for(const v of cost.views)add('| '+[v.name,n(v.baselineCalls),n(v.calls),pct(v.drawRatio),n(v.baselineTriangles),n(v.triangles)].join(' | ')+' |');
add('All five views are within +10%. Deck 10 converts all 228 outer cabins, including both ends, and remains within +5%. The added calls are deck/material or class overhead rather than one draw per converted cabin.','| Matched deck GLB | Baseline draws | Final draws | Change | Baseline triangles | Final triangles | Baseline MiB | Final MiB |','|---|---:|---:|---:|---:|---:|---:|---:|');for(const v of cost.deckComparisons)add('| '+[v.deck,n(v.baselineCalls),n(v.drawCalls),pct(v.drawRatio),n(v.baselineTriangles),n(v.triangles),m(v.baselineBytes),m(v.bytes)].join(' | ')+' |');add('Deck 19 uses '+n(Math.abs(cost.deckComparisons.find(r=>r.deck===19).drawCalls-cost.deckComparisons.find(r=>r.deck===19).baselineCalls))+' '+(cost.deckComparisons.find(r=>r.deck===19).drawCalls<cost.deckComparisons.find(r=>r.deck===19).baselineCalls?'fewer':'more')+' draws than the review baseline, replacing the prototype’s +450 garden overhead. The matched deck extraction retains whole crossing meshes. The 20-deck candidate table counts referenced final GLB primitives after facade retirement; camera counters are measured separately.','### All 20 deck costs','Interface counts use the owner’s anchor deck. Full-height garden envelopes anchored on Deck 17 also cover Decks 18 and 19; zero new anchors on those rows does not mean unconverted garden glazing.',await fs.readFile(dir+'/rollout-deck-costs.md','utf8'));
add('## Native room evidence',link('Open the eight-room image gallery','rollout-captures.html')+'. Original PNGs are 1280 × 720. Seven seated captures record successful native E interactions. The bay has no registered native seat; its lower inspection is explicitly labelled seated-height-inspection.','| Kind / room | Walk link | Standing out | Seated out | Outside in |','|---|---|---|---|---|');for(const p of cases){const images=native.captures.filter(c=>c.id===p.id),f=k=>images.find(c=>c.kind===k),seated=f('seated-out')||f('seated-height-inspection');const stand=f('standing-out'),yaw=Math.atan2(stand.look[0]-stand.eye[0],stand.look[2]-stand.eye[2])*180/Math.PI,walkURL='http://127.0.0.1:4182/walk.html?lv=2&at='+stand.walker.map(v=>v.toFixed(3)).join(',')+'&yaw='+yaw.toFixed(2)+'&pitch=0&view=first';add('| '+p.label+' · '+p.id+' | '+link('Walk here',walkURL)+' | '+link('PNG',stand.image)+' | '+link(seated.kind==='seated-out'?'E-seat PNG':'Lower inspection PNG',seated.image)+' | '+link('PNG',f('outside-in').image)+' |');}
const phoneRegressionImages=ext.rows.filter(r=>r.file==='leo-exterior-phone.glb'&&r.id==='N01-027');assert.equal(phoneRegressionImages.length,4);add('The repaired N01-027 phone window is also captured at 5, 30, 50 and 150 m: '+phoneRegressionImages.map(r=>link(r.distance+' m',r.image)).join(' · ')+'.');
add('### Whole ship and seam evidence',link('Open all four LOD seam captures and wide views','rollout-exterior-captures.html')+'. Bow, amidships, stern and garden regions are shown at about 5, 30 and 150 m in every LOD; the phone also has closest-zoom views of all eight room kinds.','| Whole-ship setting | Web | Phone |','|---|---|---|');for(const distance of [650,1000,1800]){const a=ext.rows.find(r=>r.file==='leo-exterior-web.glb'&&r.distanceSetting===distance),b=ext.rows.find(r=>r.file==='leo-exterior-phone.glb'&&r.distanceSetting===distance);add('| '+distance+' setting ('+Math.round(a.rangeMetres)+' m actual range) | '+link('PNG',a.image)+' | '+link('PNG',b.image)+' |');}
add('## Rebuild, check and view','Run these commands in PowerShell from **C:/Users/henri/code/leo-redesign**. The normal npm producer resolves Node.js 26.11.1 on this machine; direct codec, regression and harness commands also passed on Node.js 24.22.1. Packing uses native Zstd; use Node.js 24 or later. The normal v2 producers perform the rollout; scoped phase3b producers are diagnostics only.','~~~powershell','Remove-Item Env:LEO_LAYOUT -ErrorAction SilentlyContinue','npm run build','npm run build:public','npm run check',"$env:LEO_LAYOUT = '2'","$env:LEO_STARTUP_BASELINE = 'C:/Users/henri/code/leo-threejs/.qa/redesign-preview-1027b'",'npm run build','npm run build:public','npm run check:walk','npm run check','npm run check:startup','node scripts/check-startup-touch-v2.mjs','node scripts/phase3b-rollout-identity.mjs','node scripts/serve-v2.mjs 4182','~~~','Walk: http://127.0.0.1:4182/walk.html · Exterior viewer: http://127.0.0.1:4182/. Yaw 0 faces +z; yaw 90 faces +x.','The complete normal v2 npm build path and the normal public/check producers were exercised through Node child processes. The default v1 build wrapper encounters an esbuild parent-directory/Cosmo resolution denial in the sandbox; the unmodified GLB producers were completed separately. All eleven resulting GLBs match main 6a2d28a’s own after-public hashes, now pinned in src/plan/v1-models-v2.json. Default check-all passes on the merge: '+link('default check','startup-default-check-final22.log')+'. Run the first three commands above to complete the ordinary default build/public path outside the sandbox, followed by the v2 commands.','For the local evidence gallery, start a second terminal:','~~~powershell','node scripts/serve-phase3b.mjs 4183','~~~','Open http://127.0.0.1:4183/rollout-captures.html or http://127.0.0.1:4183/rollout-exterior-captures.html. The normal debug walk is http://127.0.0.1:4183/normal/walk.html.');
